using System; namespace PlacementDashboard.Admin { public partial class Dashboard : System.Web.UI.Page { protected void Page_Load(object sender,EventArgs e) { if(!IsPostBack) { StudentsGrid.DataSource=PlacementDashboard.DBConnection.GetStudents(); StudentsGrid.DataBind(); TotalStudents.Text=PlacementDashboard.DBConnection.Count("Placed") + PlacementDashboard.DBConnection.Count("Not Placed") + ""; PlacedStudents.Text=PlacementDashboard.DBConnection.Count("Placed") + ""; NotPlacedStudents.Text=PlacementDashboard.DBConnection.Count("Not Placed") + ""; } } } }
